H.background();
const m = P.m, k = P.k, L = P.L;
const g = 9.8;
const Ts = 2 * Math.PI * Math.sqrt(m / Math.max(k, 0.1));
const Tp = 2 * Math.PI * Math.sqrt(Math.max(L, 0.01) / g);
H.text("Period: spring T = 2pi*sqrt(m/k)   vs   pendulum T = 2pi*sqrt(L/g)", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("Spring period depends on mass & stiffness; pendulum on length & g (NOT on mass)", 24, 52, { color: H.colors.sub, size: 13 });
const sx = 200;
const sTop = 110;
const sAmp = 40;
const sPhase = Math.sin(2 * Math.PI * t / Ts);
const sEq = sTop + 120;
const sy = sEq + sAmp * sPhase;
H.line(sx - 50, sTop, sx + 50, sTop, { color: H.colors.grid, width: 3 });
const coils = 8;
const spr = [];
for (let i = 0; i <= coils * 4; i++) {
  const f = i / (coils * 4);
  const yy = sTop + f * (sy - sTop);
  const xx = sx + (i % 2 === 0 ? -14 : 14) * (i > 0 && i < coils * 4 ? 1 : 0);
  spr.push([xx, yy]);
}
H.path(spr, { color: H.colors.accent, width: 2 });
H.circle(sx, sy + 18, 18, { fill: H.colors.accent2, stroke: H.colors.ink, width: 2 });
H.text("SPRING", sx - 28, sTop - 16, { color: H.colors.ink, size: 13, weight: 700 });
H.text("T = " + Ts.toFixed(2) + " s", sx - 36, sy + 60, { color: H.colors.accent2, size: 13 });
const px = 650;
const pTop = 110;
const pLpx = 130;
const ampA = 0.5;
const ang = ampA * Math.sin(2 * Math.PI * t / Tp);
const bobX = px + pLpx * Math.sin(ang);
const bobY = pTop + pLpx * Math.cos(ang);
H.line(px - 60, pTop, px + 60, pTop, { color: H.colors.grid, width: 3 });
H.line(px, pTop, bobX, bobY, { color: H.colors.violet, width: 2 });
H.circle(bobX, bobY, 18, { fill: H.colors.yellow, stroke: H.colors.ink, width: 2 });
H.text("PENDULUM", px - 36, pTop - 16, { color: H.colors.ink, size: 13, weight: 700 });
H.text("T = " + Tp.toFixed(2) + " s", px - 36, bobY + 50, { color: H.colors.yellow, size: 13 });
H.text("m = " + m.toFixed(2) + " kg   k = " + k.toFixed(1) + " N/m   L = " + L.toFixed(2) + " m", 24, 78, { color: H.colors.sub, size: 13 });
H.legend([{ label: "spring  T=2pi*sqrt(m/k)", color: H.colors.accent }, { label: "pendulum  T=2pi*sqrt(L/g)", color: H.colors.violet }], 24, H.H - 40);
